const base = Math.max(0, Number(get(ctx.subtotals, 'ORDINARY_WAGES', ctx.base_pay)));
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
const category = get(ctx.subject.employment.terms, 'statutory_work_category', '');
const domestic = ['DOMESTIC', 'KASAMBAHAY'].includes(category);
const exempt = get(facts, 'statutory.SSS.elections.exempt_by_totalisation', false) === true;
const dob = get(ctx.subject.employment, 'payroll.date_of_birth', '');
const age = dob === '' ? 0 : age_on(dob, add_days(ctx.run.salary_coverage.from, -1));
const start = get(ctx.subject.employment, 'effective_range.from', '');
const before60 = get(facts, 'statutory.SSS.elections.covered_before_60', false) === true ||
	(dob !== '' && start !== '' && age_on(dob, start) < p.ordinary_coverage_age_years);
const firstMonth = domestic && start !== '' && calendar_completed_months(start, ctx.run.salary_coverage.from) < 1;
if (base <= 0) return false;
if (exempt) return false;
if (firstMonth) return false;
if (age >= p.extended_coverage_age_years) return false;
return age < p.ordinary_coverage_age_years || before60;

