employee_amount:
const p = ctx.lookup;
// PhilHealth Circular 2020-0005 s.IV.F; Advisory 2025-0002: the fixed basic rate, whole against undertime, tardiness,
// leave without pay and absences. A daily or hourly rate takes its Estimated Equivalent Monthly Rate.
const rate = Number(get(ctx.subject.employment, 'terms.rate.amount', 0));
const unit = get(ctx.subject.employment, 'terms.rate.unit', 'MONTHLY');
const days = Number(get(ctx.subject.employment, 'employee_extension_data.days_per_year', 313));
const hours = Number(get(ctx.subject.employment, 'terms.normal_hours_per_day', 8));
const monthlyBasic = unit === 'DAILY'
	? rate * days / 12
	: unit === 'HOURLY'
		? rate * hours * days / 12
		: rate;
const category = get(ctx.subject.employment.terms, 'statutory_work_category', '');
const domestic = ['DOMESTIC', 'KASAMBAHAY'].includes(category);
const base = clamp(monthlyBasic, p.minimum_salary_base, p.maximum_salary_base);
const premium = round(base * p.combined_rate, p.minor_unit, 'HALF_UP');
return domestic && monthlyBasic < p.domestic_threshold
	? 0
	: round(premium / 2, p.minor_unit, 'TRUNCATE');

