employee_amount:
// RR 2-98 s.2.78.1(A)(3): a de minimis allowance to its ceiling is not compensation and uses none of the
// PHP90,000 pool; the excess is an other benefit inside the pool. Monthly here; the semester ceiling is a sixth.
const allowance = (code) => Number(get(ctx.subject.employment, 'terms.allowances.' + code + '.amount', 0));
const deMinimis = [
	{ paid: allowance('meal'), ceiling: ctx.lookup.rice_subsidy_ceiling },
	{ paid: allowance('LAUNDRY_ALLOWANCE'), ceiling: ctx.lookup.de_minimis.laundry_monthly },
	{ paid: allowance('DEPENDANT_MEDICAL_ALLOWANCE'), ceiling: ctx.lookup.de_minimis.dependant_medical_semester / 6 }
];
const deMinimisPaid = sum(deMinimis.map((row) => Math.min(row.paid, row.ceiling)));
const deMinimisExcess = sum(deMinimis.map((row) => Math.max(0, row.paid - row.ceiling)));
const ordinary = Math.max(0, Number(get(ctx.subtotals, 'ORDINARY_WAGES', ctx.base_pay)));
const additional = Math.max(ordinary, Number(get(ctx.subtotals, 'ADDITIONAL_WAGES', ordinary)));
const total = Math.max(additional, Number(get(ctx.subtotals, 'GROSS', additional)));
const benefits = additional - ordinary + deMinimisExcess;
const residency = get(ctx.subject.employment.terms, 'residency_status', 'RESIDENT');
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
if (get(facts, 'statutory.WTAX.elections.treaty_exempt', false) === true) return 0;
if (residency === 'NON_RESIDENT_ALIEN_NETB') {
	return round(total * ctx.lookup.nonresident_rate, ctx.lookup.minor_unit, 'HALF_UP');
}
const minimumWageEarner = (() => {
	const facts = get(ctx.subject.employment, 'employee_extension_data', {});
	const employerFacts = get(ctx.subject.employer, 'entity_extension_data', {});
	if (get(employerFacts, 'bmbe_certificate_of_authority', false) === true) return false;
	const category = get(ctx.subject.employment.terms, 'statutory_work_category', '');
	const domestic = ['DOMESTIC', 'KASAMBAHAY'].includes(category);
	const region = get(facts, 'work_region', get(employerFacts, 'region', ''));
	const table = domestic ? ctx.lookup.minimum_wage_domestic : ctx.lookup.minimum_wage_by_region;
	const rates = table.filter((entry) => entry.region === region);
	if (rates.length === 0) return false;
	const day = ctx.run.salary_coverage.to;
	const applicable = rates.filter((entry) => entry.from <= day).toSorted((a, b) => a.from > b.from ? -1 : 1);
	if (applicable.length === 0) return false;
	const floor = Number(applicable[0].monthly);
	if (floor <= 0) return false;
	const terms = ctx.subject.employment.terms;
	const rate = Number(get(terms.rate, 'amount', 0));
	const unit = get(terms.rate, 'unit', 'MONTHLY');
	const annualDays = Number(get(facts, 'days_per_year', ctx.lookup.annual_paid_days));
	const hours = Number(get(terms, 'normal_hours_per_day', ctx.lookup.normal_daily_hours));
	if (domestic) {
		const monthly = unit === 'MONTHLY'
			? rate
			: unit === 'DAILY'
				? rate * ctx.lookup.annual_paid_days / 12
				: unit === 'HOURLY'
					? rate * hours * ctx.lookup.annual_paid_days / 12
					: rate;
		return monthly <= floor + 0.005;
	}
	const daily = unit === 'DAILY' ? rate : unit === 'HOURLY' ? rate * hours : rate * 12 / annualDays;
	return daily <= floor * 12 / ctx.lookup.annual_paid_days + 0.005;
})();
if (minimumWageEarner) return 0;
const contributions = Number(get(ctx.statutory, 'SSS.employee', 0)) +
	Number(get(ctx.statutory, 'SSS_MPF.employee', 0)) +
	Number(get(ctx.statutory, 'PHIC.employee', 0)) +
	Number(get(ctx.statutory, 'HDMF.employee', 0));
// RR 11-2018 s.2.79(B)(3)-(4): the period table taxes the period's total
// compensation. The annual input is the PHP90,000 13th-month/other-benefits
// pool (s.2.78.1(B)(11)); the payslip's additional_wages
// is ADDITIONAL_WAGES - ORDINARY_WAGES, so prior slips carry what this employer
// already paid this year.
const year = String(ctx.run.salary_coverage.to).slice(0, 4);
const employerId = String(get(ctx.subject.employer, 'entity_id', get(ctx.subject.employer, 'id', '')));
let benefitsYtd = 0;
for (const slip of get(ctx.history, 'payslips', [])) {
	if (String(get(slip, 'period', '')).slice(0, 4) !== year) continue;
	if (employerId !== '' && String(get(slip, 'entity_id', '')) !== employerId) continue;
	benefitsYtd += Math.max(0, Number(get(slip, 'additional_wages', 0)));
}
const ceiling = ctx.lookup.de_minimis.annual_bonus_and_other_benefits;
const exempt = Math.min(benefits, Math.max(0, ceiling - benefitsYtd));
const taxable = Math.max(0, total - deMinimisPaid - contributions - exempt);
if (taxable <= 0) return 0;
const days = calendar_distance_days(ctx.run.salary_coverage.from, ctx.run.salary_coverage.to) + 1;
const bands = days <= 1
	? ctx.lookup.daily_tax
	: days <= 7
		? ctx.lookup.weekly_tax
		: days <= 16
			? ctx.lookup.semi_monthly_tax
			: ctx.lookup.monthly_tax;
return round(ladder(taxable, bands), ctx.lookup.minor_unit, 'HALF_UP');

